// SPDX-FileCopyrightText: 2026 Alexandre 'kidev' Poumaroux
// SPDX-License-Identifier: Apache-2.0

import SynQt
import QtQuick.Controls
import QtQuick.Layouts

// The browser view of the auction (docs/tutorial-base-auction.md, -sign-in.md,
// -hall-of-fame.md). `Server` reaches the edge's connect points; `Session` is the read-only
// view of who you are. Every check here is a courtesy. The edge is the authority.
ApplicationWindow {
    id: window

    // The client's Main.qml is the window itself, the shape `synqt new` scaffolds and
    // docs/examples.md shows. QQmlApplicationEngine only shows a root object that IS a
    // window, so a bare Page root here would load without error and render nothing.
    visible: true
    width: 480
    height: 420
    title: "Gavel"

    ColumnLayout {
        anchors.fill: parent
        anchors.margins: 16
        spacing: 12

        Label {
            text: Server.itemName
            font.pixelSize: 22
            Layout.fillWidth: true
            wrapMode: Text.WordWrap
        }

        // Updates by itself whenever the edge changes it.
        Label {
            text: "Current bid: " + Server.highBid
                  + "  (held by " + Server.highBidder + ")"
            font.pixelSize: 18
        }

        // Signed out. Offer sign in. Watching the auction stays open to everyone.
        RowLayout {
            spacing: 8
            visible: !Session.hasScope("user")
            Button {
                text: "Sign in to bid"
                onClicked: Session.login()
            }
        }

        // Signed in. Show who you are and the bid controls.
        RowLayout {
            spacing: 8
            visible: Session.hasScope("user")
            Label {
                text: "Signed in as " + (Session.identity ? Session.identity.name : "")
            }
            TextField {
                id: amountField
                placeholderText: "Amount"
                inputMethodHints: Qt.ImhDigitsOnly
            }
            Button {
                text: "Place bid"
                onClicked: {
                    Server.placeBid(parseInt(amountField.text));
                    amountField.clear();
                }
            }
        }

        // The auctioneer (admin) can close a lot and open the next.
        RowLayout {
            spacing: 8
            visible: Session.hasScope("admin")
            TextField { id: nextItemField; placeholderText: "Next item" }
            Button {
                text: "Close lot"
                onClicked: Server.closeLot(nextItemField.text)
            }
        }

        Label {
            id: errorLabel
            color: "crimson"
            visible: text.length > 0
        }

        Label { text: "Hall of Fame"; font.pixelSize: 18 }

        ListView {
            Layout.fillWidth: true
            Layout.fillHeight: true
            model: Server.winners
            delegate: Label {
                required property string winner
                required property string item
                required property int amount
                text: winner + " won " + item + " for " + amount
            }
        }

        // Listen for a rejection meant for this caller. The attached handler names the contract, which
        // is the owner's name (`Edge`), where the calls above go through `Server`, the client's
        // alias for whichever edge it is attached to.
        Edge.onBidRejected: reason => errorLabel.text = reason
    }
}

// SPDX-FileCopyrightText: 2026 Alexandre 'kidev' Poumaroux
// SPDX-License-Identifier: Apache-2.0

import SynQt

// The web edge (docs/tutorial-sign-in.md and docs/tutorial-hall-of-fame.md): the live
// auction, and the Hall of Fame filled from the books entity. This one file is the entity
// and the surface it exports; the edge is shared, so there is one of it holding one lot,
// however many browsers are watching, and each caller still arrives with their own `Caller`.
//
// Who may call what is on the members themselves, in the `export:` block: `placeBid` is
// gated on `user` and `closeLot` on `admin`, and a caller without the scope never reaches
// the function at all. What is left here is the part the topology cannot decide, which is
// whether this particular bid is good enough.
Edge {
    id: lot

    // Newest first, capped. Only the declared roles of the `winners` model reach a browser.
    property var winners: []

    itemName: "A homemade lasagna, baked fresh this morning"
    highBid: 0
    highBidder: "nobody yet"
    // `winnersRows` keeps only the roles the contract declares, so nothing the ledger holds
    // beyond them reaches a browser. One binding, so a new winner arriving at the entity
    // reaches every session with nothing else written.
    winnersRows: lot.winners

    // `Books` is how the edge reaches the books entity, the same way the browser reaches
    // the edge with `Server`. An entity has one connect point, so its name is the whole
    // address.
    Component.onCompleted: Books.winnerRecorded.connect(lot.recordWinner)

    // A signed-in user is asking to bid. Whether their bid is good enough is ours to say.
    function placeBid(amount) {
        if (amount <= lot.highBid) {
            Caller.emitBidRejected("Your bid must beat " + lot.highBid + ".");
            return;
        }
        lot.highBid = amount;
        lot.highBidder = Caller.identity.name;       // their real name, from sign in
    }

    // The auctioneer closes the current lot and opens the next one. The winner is recorded
    // permanently in the books entity before the reset.
    function closeLot(nextItem) {
        if (lot.highBid > 0) {
            Books.recordWinner(lot.itemName, lot.highBidder, lot.highBid);
        }
        lot.itemName = nextItem;
        lot.highBid = 0;
        lot.highBidder = "nobody yet";
    }

    function recordWinner(item: string, winner: string, amount: int) {
        const next = [{
                "item": item,
                "winner": winner,
                "amount": amount
            }].concat(lot.winners);
        lot.winners = next.slice(0, 20);
    }
}

// SPDX-FileCopyrightText: 2026 Alexandre 'kidev' Poumaroux
// SPDX-License-Identifier: Apache-2.0

import SynQt

// The authoritative ledger on the books entity (docs/tutorial-hall-of-fame.md).
//
// There is no check in here for who is calling, and that is the point: the connect point
// lists one consumer, the edge, so the mesh opens no link to anything else and nothing else
// can acquire this. A browser cannot reach it at all. Where an entity does have two
// consumers and only one of them may write, that is what `Caller.entity` is for.
//
// The Db helper (parameterized query/exec, so a value can never become SQL) backs the
// durable store when the persistence blueprint provisions it; this in-memory store keeps
// the connect-point contract identical while the tutorial's SQLite provider is wired in.
Books {
    id: point

    property var store: []

    function recordWinner(item, winner, amount) {
        point.store.push({ item: item, winner: winner, amount: amount });
        point.count = point.store.length;
        point.winnerRecorded(item, winner, amount);   // announce to the edge
    }
}

